script:
frappe.ui.form.on('Disciplinary', {
    refresh(frm) {
        if (frm.is_new()) return;

        // Roles allowed to perform HR actions
        const allowed_roles = [
            "HR Manager",
            "Hr User",
            "Human Resource Manager",
            "Human Resource Officer - Employee Welfare"
        ];

        const has_hr_access = allowed_roles.some(role =>
            frappe.user.has_role(role)
        );

        // Prevent non-HR users from seeing the buttons
        if (!has_hr_access) {
            return;
        }

        // Workflow states where buttons should appear
        const allowed_states = [
            "Recommendation of Charge",
            "Case Closed"
        ];

        if (allowed_states.includes(frm.doc.workflow_state)) {
            add_forced_leave_button(frm);
            add_salary_withholding_button(frm);
            add_half_pay_button(frm);
            add_employee_separation_button(frm);
        }
    }
});

// ============================================================
// FORCED LEAVE BUTTON
// ============================================================

function add_forced_leave_button(frm) {
    frm.add_custom_button(__('Forced Leave'), function () {
        frappe.confirm(
            `Are you sure you want to initiate <strong>Forced Leave</strong> for ` +
            `<strong>${frm.doc.employee_name}</strong>?`,
            function () {
                let d = new frappe.ui.Dialog({
                    title: 'Initiate Forced Leave',
                    fields: [
                        {
                            fieldtype:  'Link',
                            fieldname:  'leave_type',
                            label:      'Leave Type',
                            options:    'Leave Type',
                            reqd:       1
                        },
                        {
                            fieldtype:  'Date',
                            fieldname:  'start_date',
                            label:      'Start Date',
                            reqd:       1,
                            default:    frappe.datetime.get_today()
                        },
                        {
                            fieldtype:  'Date',
                            fieldname:  'end_date',
                            label:      'End Date',
                            reqd:       1
                        },
                        {
                            fieldtype:  'Small Text',
                            fieldname:  'reason',
                            label:      'Reason for Forced Leave',
                            reqd:       1,
                            default:    `Disciplinary Case: ${frm.doc.name}`
                        }
                    ],
                    primary_action_label: 'Create Forced Leave',
                    primary_action(values) {
                        frappe.call({
                            method: 'frappe.client.insert',
                            args: {
                                doc: {
                                    doctype:              'Forced leave',
                                    employee:             frm.doc.employee,
                                    employee_name:        frm.doc.employee_name,
                                    department:           frm.doc.department,
                                    designation:          frm.doc.designation,
                                    disciplinary_case_no: frm.doc.name,
                                    leave_type:           values.leave_type,
                                    start_date:           values.start_date,
                                    end_date:             values.end_date,
                                    reason:               values.reason
                                }
                            },
                            callback(r) {
                                if (!r.exc) {
                                    d.hide();
                                    frappe.show_alert({
                                        message:   __('Forced Leave created successfully.'),
                                        indicator: 'green'
                                    }, 5);
                                    frappe.set_route('Form', 'Forced Leave', r.message.name);
                                }
                            }
                        });
                    }
                });
                d.show();
            }
        );
    }, __('HR Actions'));
}


// ============================================================
// SALARY WITHHOLDING BUTTON
// ============================================================

function add_salary_withholding_button(frm) {
    frm.add_custom_button(__('Salary Withholding'), function () {
        frappe.confirm(
            `Are you sure you want to initiate <strong>Salary Withholding</strong> for ` +
            `<strong>${frm.doc.employee_name}</strong>?`,
            function () {
                let d = new frappe.ui.Dialog({
                    title: 'Initiate Salary Withholding',
                    fields: [
                        {
                            fieldtype:  'Select',
                            fieldname:  'payroll_frequency',
                            label:      'Payroll Frequency',
                            options:    'Monthly\nBimonthly\nFortnightly\nWeekly\nDaily',
                            reqd:       1,
                            default:    'Monthly'
                        },
                        {
                            fieldtype:  'Int',
                            fieldname:  'number_of_withholding_cycles',
                            label:      'Number of Withholding Cycles',
                            reqd:       1,
                            default:    1
                        },
                        {
                            fieldtype:  'Date',
                            fieldname:  'from_date',
                            label:      'From Date',
                            reqd:       1,
                            default:    frappe.datetime.get_today()
                        },
                        {
                            fieldtype:  'Date',
                            fieldname:  'to_date',
                            label:      'To Date',
                            reqd:       1
                        },
                        {
                            fieldtype:  'Small Text',
                            fieldname:  'reason',
                            label:      'Reason for Withholding Salary',
                            reqd:       1,
                            default:    `Disciplinary Case: ${frm.doc.name}`
                        }
                    ],
                    primary_action_label: 'Create Salary Withholding',
                    primary_action(values) {
                        frappe.call({
                            method: 'frappe.client.insert',
                            args: {
                                doc: {
                                    doctype:                       'Salary Withholding',
                                    employee:                      frm.doc.employee,
                                    employee_name:                 frm.doc.employee_name,
                                    posting_date:                  frappe.datetime.get_today(),
                                    payroll_frequency:             values.payroll_frequency,
                                    number_of_withholding_cycles:  values.number_of_withholding_cycles,
                                    start_date:                     values.from_date,
                                    end_date:                       values.to_date,
                                    reason:                        values.reason,
                                    status:                        'Active'
                                }
                            },
                            callback(r) {
                                if (!r.exc) {
                                    d.hide();
                                    frappe.show_alert({
                                        message:   __('Salary Withholding created successfully.'),
                                        indicator: 'green'
                                    }, 5);
                                    frappe.set_route('Form', 'Salary Withholding', r.message.name);
                                }
                            }
                        });
                    }
                });
                d.show();
            }
        );
    }, __('HR Actions'));
}


// ============================================================
// HALF PAY BUTTON
// ============================================================
// Fetches the employee's current active Salary Structure Assignment,
// reads the base amount, halves it, and creates a new assignment
// with the half-pay base. The from_date defaults to today.
//
// ASSUMPTIONS:
//   • The Salary Structure Assignment doctype has fields:
//       employee, salary_structure, from_date, base, company
//   • The most recent active assignment is fetched by ordering
//     by from_date descending.
//   • A new assignment is inserted (not amending the old one)
//     so there is a clear audit trail.
//   • When the disciplinary matter is resolved, HR must manually
//     create a new assignment to restore full pay.

function add_half_pay_button(frm) {
    frm.add_custom_button(__('Half Pay'), function () {

        // Step 1: fetch current Salary Structure Assignment
        frappe.call({
            method: 'frappe.client.get_list',
            args: {
                doctype:          'Salary Structure Assignment',
                filters: [
                    ['employee',  '=', frm.doc.employee],
                    ['docstatus', '=', 1]          // only submitted assignments
                ],
                fields:           ['name', 'salary_structure', 'base', 'from_date', 'company'],
                order_by:         'from_date desc',
                limit_page_length: 1
            },
            callback(r) {
                if (!r.message || r.message.length === 0) {
                    frappe.msgprint({
                        title:     __('No Salary Structure Assignment Found'),
                        indicator: 'orange',
                        message:   __(
                            `No submitted Salary Structure Assignment found for ` +
                            `<b>${frm.doc.employee_name}</b>. Please assign a salary ` +
                            `structure before initiating half pay.`
                        )
                    });
                    return;
                }

                const current = r.message[0];

                if (!current.base || current.base <= 0) {
                    frappe.msgprint({
                        title:     __('Base Salary Not Set'),
                        indicator: 'orange',
                        message:   __(
                            `The current Salary Structure Assignment (<b>${current.name}</b>) ` +
                            `does not have a base amount set. Please update the assignment ` +
                            `before using Half Pay.`
                        )
                    });
                    return;
                }

                const full_base = current.base;
                const half_base = full_base / 2;

                // Step 2: confirm with the user, showing current vs half-pay amounts
                frappe.confirm(
                    `<b>Half Pay — Salary Structure Update</b><br><br>
                    <table style="width:100%;border-collapse:collapse;font-size:13px;">
                        <tr>
                            <td style="padding:4px 8px;color:#666;">Employee</td>
                            <td style="padding:4px 8px;font-weight:600;">${frm.doc.employee_name}</td>
                        </tr>
                        <tr style="background:#f9f9f9;">
                            <td style="padding:4px 8px;color:#666;">Current Base</td>
                            <td style="padding:4px 8px;font-weight:600;">
                                ${frappe.format(full_base, { fieldtype: 'Currency' })}
                            </td>
                        </tr>
                        <tr>
                            <td style="padding:4px 8px;color:#666;">Half Pay Base</td>
                            <td style="padding:4px 8px;font-weight:600;color:#C0392B;">
                                ${frappe.format(half_base, { fieldtype: 'Currency' })}
                            </td>
                        </tr>
                        <tr style="background:#f9f9f9;">
                            <td style="padding:4px 8px;color:#666;">Salary Structure</td>
                            <td style="padding:4px 8px;">${current.salary_structure}</td>
                        </tr>
                    </table><br>
                    A new Salary Structure Assignment will be created at <b>50% base pay</b>. 
                    The previous assignment remains as a record. 
                    <br><br>
                    <b>Note:</b> You will need to manually restore full pay once the 
                    disciplinary matter is resolved.`,

                    function () {
                        // Step 3: show a dialog to confirm the effective date
                        let d = new frappe.ui.Dialog({
                            title: 'Confirm Half Pay Effective Date',
                            fields: [
                                {
                                    fieldtype:   'Date',
                                    fieldname:   'from_date',
                                    label:       'Effective From',
                                    reqd:        1,
                                    default:     frappe.datetime.get_today(),
                                    description: 'The date from which the half-pay salary structure takes effect.'
                                },
                                {
                                    fieldtype:   'Small Text',
                                    fieldname:   'reason',
                                    label:       'Reason',
                                    reqd:        1,
                                    default:     `Half Pay — Disciplinary Case ${frm.doc.name}`
                                }
                            ],
                            primary_action_label: 'Apply Half Pay',
                            primary_action(values) {

                                // Step 4: insert new Salary Structure Assignment at 50%
                                frappe.call({
                                    method: 'frappe.client.insert',
                                    args: {
                                        doc: {
                                            doctype:           'Salary Structure Assignment',
                                            employee:          frm.doc.employee,
                                            salary_structure:  current.salary_structure,
                                            company:           current.company,
                                            start_date:         values.from_date,
                                            base:              half_base,
                                            // Store the reason in a custom field if it exists;
                                            // harmless if the field is absent
                                            half_pay_reason:   values.reason,
                                            disciplinary_case_no: frm.doc.name,
                    leave_type: 'Forced Leave'
                                        }
                                    },
                                    callback(r) {
                                        if (r.exc) return;

                                        const new_name = r.message.name;

                                        // Step 5: submit the new assignment
                                        frappe.call({
                                            method: 'frappe.client.submit',
                                            args:   { doctype: 'Salary Structure Assignment', name: new_name },
                                            callback(res) {
                                                d.hide();

                                                if (res.exc) {
                                                    frappe.msgprint({
                                                        title:     __('Assignment Created but Not Submitted'),
                                                        indicator: 'orange',
                                                        message:   __(
                                                            `Half Pay assignment <b>${new_name}</b> was created ` +
                                                            `but could not be submitted automatically. ` +
                                                            `Please open and submit it manually.`
                                                        )
                                                    });
                                                    window.open(
                                                        `/app/salary-structure-assignment/${new_name}`,
                                                        '_blank'
                                                    );
                                                    return;
                                                }

                                                frappe.show_alert({
                                                    message: __(
                                                        `Half Pay applied. New assignment <b>${new_name}</b> ` +
                                                        `effective ${values.from_date}.`
                                                    ),
                                                    indicator: 'green'
                                                }, 8);

                                                // Open the new assignment for reference
                                                window.open(
                                                    `/app/salary-structure-assignment/${new_name}`,
                                                    '_blank'
                                                );
                                            }
                                        });
                                    }
                                });
                            }
                        });
                        d.show();
                    }
                );
            }
        });

    }, __('HR Actions'));
}


// ============================================================
// EMPLOYEE SEPARATION BUTTON
// ============================================================

function add_employee_separation_button(frm) {
    frm.add_custom_button(__('Employee Separation'), function () {
        frappe.confirm(
            `Are you sure you want to initiate <strong>Employee Separation</strong> for ` +
            `<strong>${frm.doc.employee_name}</strong>? ` +
            `This should only be done after a formal decision has been reached.`,
            function () {
                let d = new frappe.ui.Dialog({
                    title: 'Initiate Employee Separation',
                    fields: [
                        {
                            fieldtype: 'Select',
                            fieldname: 'separation_reason',
                            label:     'Separation Reason',
                            options: [
                                'Resignation',
                                'Retirement',
                                'Contract Expiry',
                                'Termination',
                                'Dismissal',
                                'Redundancy',
                                'Death in Service',
                                'Medical Grounds',
                                'Mutual Separation',
                                'Abscondment',
                                'End of Probation',
                                'Other'
                            ].join('\n'),
                            reqd:    1,
                            default: 'Dismissal'
                        },
                        {
                            fieldtype: 'Date',
                            fieldname: 'boarding_begins_on',
                            label:     'Separation Begins On',
                            reqd:      1,
                            default:   frappe.datetime.get_today()
                        },
                        {
                            fieldtype: 'Date',
                            fieldname: 'resignation_letter_date',
                            label:     'Resignation / Dismissal Letter Date'
                        },
                        {
                            fieldtype: 'Text Editor',
                            fieldname: 'exit_interview',
                            label:     'Exit Interview Summary'
                        }
                    ],
                    primary_action_label: 'Create Employee Separation',
                    primary_action(values) {
                        frappe.call({
                            method: 'frappe.client.insert',
                            args: {
                                doc: {
                                    doctype:                  'Employee Separation',
                                    employee:                 frm.doc.employee,
                                    employee_name:            frm.doc.employee_name,
                                    department:               frm.doc.department,
                                    designation:              frm.doc.designation,
                                    separation_reason:        values.separation_reason,
                                    boarding_begins_on:       values.boarding_begins_on,
                                    resignation_letter_date:  values.resignation_letter_date,
                                    exit_interview:           values.exit_interview,
                                    reference_doctype:        'Disciplinary',
                                    reference_document:       frm.doc.name,
                                    boarding_status:          'Pending',
                                    notify_users_by_email:    1
                                }
                            },
                            callback(r) {
                                if (!r.exc) {
                                    d.hide();
                                    frappe.show_alert({
                                        message:   __('Employee Separation created successfully.'),
                                        indicator: 'green'
                                    }, 5);
                                    frappe.set_route('Form', 'Employee Separation', r.message.name);
                                }
                            }
                        });
                    }
                });
                d.show();
            }
        );
    }, __('HR Actions'));
}

// ============================================================
// ERPNext Client Script — Disciplinary Doctype  (v5)
// ============================================================

// ── Debounce utility ─────────────────────────────────────────
const _debounce_timers = {};
function debounce_call(key, fn, delay_ms) {
    if (_debounce_timers[key]) clearTimeout(_debounce_timers[key]);
    _debounce_timers[key] = setTimeout(fn, delay_ms || 600);
}


// ============================================================
// MAIN FORM EVENTS
// ============================================================

frappe.ui.form.on('Disciplinary', {

    setup(frm) {
        frm.set_indicator_formatter('specific_offence', (row) => {
            return row.prescribed_sanction === 'Summary Dismissal' ? 'red' : 'green';
        });
    },

    onload(frm) {
        if (frm.doc.employee && frm.doc.charge_description) {
            frm.doc.charge_description.forEach((row) => {
                if (row.specific_offence && !row.breach_number) {
                    debounce_call(
                        'breach_' + row.name,
                        () => calculate_breach_number(frm, row),
                        800
                    );
                }
            });
        }
    },

    refresh(frm) {
        show_stage_guidance(frm);
        setup_custom_buttons(frm);

        if (frm.doc.workflow_state === 'Hearing Outcome') {
            populate_verdict_from_charges(frm);
        }
        if (frm.doc.workflow_state === 'Appeal Outcome') {
            populate_appeal_verdict_from_verdict(frm);
        }
    },

    workflow_state(frm) {
        handle_workflow_state_change(frm);
    },

    select_jhxk(frm) {
        if (frm.doc.select_jhxk === 'Unsatisfactory Proceed to Hearing') {
            populate_verdict_from_charges(frm);
        }
    },

    select_outcome(frm) {
        if (frm.doc.select_outcome === 'Satisfactory' && has_summary_dismissal(frm)) {
            frappe.msgprint({
                title: __('Summary Dismissal \u2014 Hearing Required'),
                indicator: 'red',
                message: __('One or more charges carry a <b>Summary Dismissal</b> sanction. ' +
                    'This case must proceed to a Disciplinary Hearing, so the exculpation ' +
                    'cannot be recorded as <b>Satisfactory</b>. Select <b>Not Satisfactory</b>.')
            });
            frm.set_value('select_outcome', 'Not Satisfactory');
        }
    },

    hearing_decision(frm) {
        if (['Warning', 'Verbal Warning'].includes(frm.doc.hearing_decision)) {
            prompt_warning_comment(frm, frm.doc.hearing_decision);
        }
    },

    validate(frm) {
        validate_mandatory_by_state(frm);
    }
});


// ============================================================
// DISCIPLINARY CHARGES CHILD TABLE EVENTS
// ============================================================

frappe.ui.form.on('Disciplinary Charges', {

    specific_offence(frm, cdt, cdn) {
        const row = locals[cdt][cdn];
        if (!row.specific_offence) return;

        frappe.db.get_value(
            'Offence Master',
            row.specific_offence,
            ['definition', 'offence_code', 'offence_category'],
            (r) => {
                if (r && r.definition) {
                    frappe.model.set_value(cdt, cdn, 'description', r.definition);
                }
            }
        );

        debounce_call(
            'breach_calc_' + cdn,
            () => calculate_breach_number(frm, row, cdt, cdn),
            700
        );
    },

    breach_number(frm, cdt, cdn) {
        const row = locals[cdt][cdn];
        if (row.specific_offence && row.breach_number) {
            fetch_prescribed_sanction(frm, cdt, cdn, row);
        }
    },

    charge_description_remove(frm) {
        update_summary_dismissal_flag(frm);
    }
});


// ============================================================
// VERDICT CHILD TABLE EVENTS
// ============================================================

frappe.ui.form.on('Verdict', {
    verdict(frm, cdt, cdn) {
        const row = locals[cdt][cdn];
        if (row.prescribed_sanction === 'Summary Dismissal' && row.verdict === 'Not Guilty') {
            frappe.msgprint({
                title: __('Notice'),
                indicator: 'orange',
                message: __(
                    'This charge carries a Summary Dismissal sanction. Even with a Not Guilty ' +
                    'finding, the matter must still proceed through the hearing process and a ' +
                    'verdict must be formally recorded.'
                )
            });
        }
    }
});


// ============================================================
// APPEAL VERDICT CHILD TABLE EVENTS
// ============================================================

frappe.ui.form.on('Appeal Verdict', {
    appeal_decision(frm, cdt, cdn) {
        // Reserved for future per-row logic
    }
});


// ============================================================
// SUMMARY DISMISSAL FLAG HELPER
// ============================================================

function update_summary_dismissal_flag(frm) {
    const has_sd = has_summary_dismissal(frm) ? 1 : 0;
    if (frm.fields_dict['has_summary_dismissal']) {
        frm.set_value('has_summary_dismissal', has_sd);
    }
}

function has_summary_dismissal(frm) {
    return (frm.doc.charge_description || []).some(
        row => row.prescribed_sanction === 'Summary Dismissal'
    );
}

function guard_summary_dismissal(frm) {
    if (frm.doc.workflow_state === 'Exculpation Evaluation' && has_summary_dismissal(frm)) {
        frappe.msgprint({
            title: __('⚠ Summary Dismissal — Hearing Required'),
            indicator: 'red',
            message: __(
                'One or more charges carry a <b>Summary Dismissal</b> sanction. ' +
                'This case <b>must proceed to a Disciplinary Hearing</b> regardless of the ' +
                'exculpation outcome. You may only select <b>"Non Satisfactory and Dismissible"</b>.'
            )
        });
        return false;
    }
    return true;
}


// ============================================================
// MANDATORY FIELD VALIDATION BY WORKFLOW STATE
// ============================================================

function validate_mandatory_by_state(frm) {
    const state = frm.doc.workflow_state;

    if (state === 'Charge') {
        if (!frm.doc.charge_description || frm.doc.charge_description.length === 0) {
            frappe.msgprint({
                title: __('Validation Error'),
                indicator: 'red',
                message: __('Please add at least one charge in the <b>Charge Description</b> table before proceeding.')
            });
            frappe.validated = false;
            return;
        }

        for (let i = 0; i < frm.doc.charge_description.length; i++) {
            const row = frm.doc.charge_description[i];
            if (!row.specific_offence) {
                frappe.msgprint({
                    title: __('Validation Error'),
                    indicator: 'red',
                    message: __(`Row ${i + 1} in Charge Description is missing the <b>Specific Offence</b>.`)
                });
                frappe.validated = false;
                return;
            }
        }
    }

    if (state === 'Exculpation Evaluation') {
        if (!frm.doc.select_outcome) {
            frappe.msgprint({
                title: __('Validation Error'),
                indicator: 'red',
                message: __('Please select the <b>Exculpation Outcome</b> before saving.')
            });
            frappe.validated = false;
            return;
        }
    }
}


// ============================================================
// BREACH CALCULATION
// ============================================================

function calculate_breach_number(frm, row, cdt, cdn) {
    if (!frm.doc.employee || !row.specific_offence) return;

    const today = frappe.datetime.get_today();

    frappe.call({
        method: 'frappe.client.get_list',
        args: {
            doctype: 'Disciplinary',
            filters: [
                ['employee',       '=',  frm.doc.employee],
                ['name',           '!=', frm.doc.name || ''],
                ['workflow_state', '=',  'Case Closed']
            ],
            fields: ['name'],
            limit_page_length: 200
        },
        callback(r) {
            if (!r.message || r.message.length === 0) {
                set_breach_and_sanction(frm, cdt, cdn, row, '1st Breach');
                return;
            }

            const prior_case_names = r.message.map(d => d.name);
            let   active_warnings  = [];
            let   pending_calls    = prior_case_names.length;

            prior_case_names.forEach((case_name) => {
                frappe.db.get_doc('Disciplinary', case_name).then((prior_doc) => {
                    if (prior_doc && prior_doc.charge_description) {
                        prior_doc.charge_description.forEach((charge) => {
                            if (charge.specific_offence !== row.specific_offence) return;

                            const expiry = charge.warning_expiry_date;
                            if (!expiry) return;

                            const expiry_obj = frappe.datetime.str_to_obj(expiry);
                            const today_obj  = frappe.datetime.str_to_obj(today);

                            if (expiry_obj >= today_obj) {
                                active_warnings.push({
                                    sanction: charge.prescribed_sanction,
                                    expiry,
                                    case: case_name
                                });
                            }
                        });
                    }

                    pending_calls--;

                    if (pending_calls === 0) {
                        const breach_count  = active_warnings.length + 1;
                        const breach_map    = { 1: '1st Breach', 2: '2nd Breach', 3: '3rd Breach', 4: '4th Breach' };
                        const breach_number = breach_map[breach_count] || '4th Breach';

                        set_breach_and_sanction(frm, cdt, cdn, row, breach_number);

                        if (active_warnings.length > 0) {
                            frappe.msgprint({
                                title: __('Active Prior Warnings Found'),
                                indicator: 'orange',
                                message: __(
                                    `Found <b>${active_warnings.length}</b> active prior warning(s) ` +
                                    `for <b>${row.specific_offence}</b> in closed cases. ` +
                                    `Breach set to <b>${breach_number}</b>.`
                                )
                            });
                        }
                    }
                });
            });
        }
    });
}

function set_breach_and_sanction(frm, cdt, cdn, row, breach_number) {
    frappe.model.set_value(cdt, cdn, 'breach_number', breach_number);

    frappe.call({
        method: 'frappe.client.get_list',
        args: {
            doctype: 'Offence Sanction Matrix',
            filters: [
                ['offence',        '=', row.specific_offence],
                ['breach_number',  '=', breach_number]
            ],
            fields: ['prescribed_sanction'],
            limit_page_length: 1
        },
        callback(r) {
            if (r.message && r.message.length > 0) {
                const sanction = r.message[0].prescribed_sanction;
                frappe.model.set_value(cdt, cdn, 'prescribed_sanction', sanction);
                set_warning_expiry(cdt, cdn, sanction);

                if (sanction === 'Summary Dismissal') {
                    update_summary_dismissal_flag(frm);
                    frappe.msgprint({
                        title: __('⚠ Summary Dismissal'),
                        indicator: 'red',
                        message: __(
                            `The prescribed sanction for <b>${row.specific_offence}</b> ` +
                            `(${breach_number}) is <b>Summary Dismissal</b>. ` +
                            `This case will proceed to a Disciplinary Hearing.`
                        )
                    });
                }
            } else {
                frappe.msgprint({
                    title: __('Sanction Not Found'),
                    indicator: 'orange',
                    message: __(
                        `No sanction found for <b>${row.specific_offence}</b> at ` +
                        `<b>${breach_number}</b>. Verify the Offence Sanction Matrix.`
                    )
                });
            }
            frm.refresh_field('charge_description');
        }
    });
}

function fetch_prescribed_sanction(frm, cdt, cdn, row) {
    frappe.call({
        method: 'frappe.client.get_list',
        args: {
            doctype: 'Offence Sanction Matrix',
            filters: [
                ['offence',       '=', row.specific_offence],
                ['breach_number', '=', row.breach_number]
            ],
            fields: ['prescribed_sanction'],
            limit_page_length: 1
        },
        callback(r) {
            if (r.message && r.message.length > 0) {
                frappe.model.set_value(cdt, cdn, 'prescribed_sanction', r.message[0].prescribed_sanction);
                set_warning_expiry(cdt, cdn, r.message[0].prescribed_sanction);
                frm.refresh_field('charge_description');
            }
        }
    });
}

function set_warning_expiry(cdt, cdn, sanction) {
    let expiry_date = null;
    const today = frappe.datetime.get_today();
    const s = (sanction || '').toLowerCase();

    if (s.includes('verbal warning')) {
        expiry_date = frappe.datetime.add_months(today, 6);
    } else if (s.includes('final warning') || s.includes('written warning')) {
        expiry_date = frappe.datetime.add_months(today, 12);
    }
    frappe.model.set_value(cdt, cdn, 'warning_expiry_date', expiry_date);
}


// ============================================================
// POPULATE VERDICT TABLES
// ============================================================

function populate_verdict_from_charges(frm) {
    if (!frm.doc.charge_description || frm.doc.charge_description.length === 0) return;

    const existing = (frm.doc.hearing_outcome || [])
        .map(r => r.specific_offence)
        .filter(Boolean);

    let added = 0;
    frm.doc.charge_description.forEach((charge) => {
        if (!charge.specific_offence) return;
        if (existing.includes(charge.specific_offence)) return;

        let new_row = frm.add_child('hearing_outcome');
        frappe.model.set_value(new_row.doctype, new_row.name, 'specific_offence', charge.specific_offence);
        frappe.model.set_value(new_row.doctype, new_row.name, 'deescription', charge.description);
        frappe.model.set_value(new_row.doctype, new_row.name, 'breach_number', charge.breach_number);
        frappe.model.set_value(new_row.doctype, new_row.name, 'prescribed_sanction', charge.prescribed_sanction);
        frappe.model.set_value(new_row.doctype, new_row.name, 'charge_comments', charge.comments);
        existing.push(charge.specific_offence);
        added++;
    });

    if (added > 0) {
        frm.refresh_field('hearing_outcome');
    }
}

function populate_appeal_verdict_from_verdict(frm) {
    if (!frm.doc.hearing_outcome || frm.doc.hearing_outcome.length === 0) return;

    const existing = (frm.doc.appeal_verdict || [])
        .map(r => r.specific_offence)
        .filter(Boolean);

    let added = 0;
    frm.doc.hearing_outcome.forEach((verdict) => {
        if (!verdict.specific_offence) return;
        if (existing.includes(verdict.specific_offence)) return;

        let new_row = frm.add_child('appeal_verdict');
        frappe.model.set_value(new_row.doctype, new_row.name, 'specific_offence', verdict.specific_offence);
        frappe.model.set_value(new_row.doctype, new_row.name, 'description', verdict.deescription);
        frappe.model.set_value(new_row.doctype, new_row.name, 'breach_number', verdict.breach_number);
        frappe.model.set_value(new_row.doctype, new_row.name, 'prescribed_sanction', verdict.prescribed_sanction);
        frappe.model.set_value(new_row.doctype, new_row.name, 'original_verdict', verdict.verdict);
        frappe.model.set_value(new_row.doctype, new_row.name, 'original_verdict_notes', verdict.hearing_notes || '');
        existing.push(verdict.specific_offence);
        added++;
    });

    if (added > 0) {
        frm.refresh_field('appeal_verdict');
    }
}


// ============================================================
// WORKFLOW STATE CHANGE HANDLER
// ============================================================

function handle_workflow_state_change(frm) {
    const state = frm.doc.workflow_state;

    if (state === 'Issue Warning') {
        show_warning_prompt(
            frm,
            'Warning',
            'warning',
            `A warning is being issued to <b>${frm.doc.employee_name || frm.doc.employee}</b>. ` +
            `Enter the formal warning statement to be recorded in the Warning tab:`
        );
    }

    if (state === 'Outcome Evaluation') {
        show_warning_prompt(frm, 'Hearing Warning', 'hearing_warning', 'Enter the hearing warning statement:');
    }

    if (state === 'Exculpation Evaluation') {
        frm.page.btn_primary.off('click.sd_guard').on('click.sd_guard', function () {
            if (has_summary_dismissal(frm)) {
                guard_summary_dismissal(frm);
            }
        });
    }

    if (state === 'Hearing Outcome') {
        populate_verdict_from_charges(frm);
    }
    if (state === 'Appeal Outcome') {
        populate_appeal_verdict_from_verdict(frm);
    }

    show_stage_guidance(frm);
}


