}


// ============================================================
// SUMMARY DISMISSAL — OUTCOME CHECK
// ============================================================

function outcome_is_summary_dismissal(frm) {
    return (frm.doc.hearing_outcome || []).some(
        row => row.prescribed_sanction === 'Summary Dismissal' && row.verdict === 'Guilty'
    );
}

function create_employee_separation(frm) {
    frappe.confirm(
        `This will create an <b>Employee Separation</b> record for ` +
        `<b>${frm.doc.employee_name || frm.doc.employee}</b> with reason <b>Dismissal</b>. Proceed?`,
        () => {
            frappe.call({
                method: 'frappe.client.insert',
                args: {
                    doc: {
                        doctype:                'Employee Separation',
                        employee:               frm.doc.employee,
                        employee_name:          frm.doc.employee_name,
                        department:             frm.doc.department,
                        designation:            frm.doc.designation,
                        reason_for_resignation: 'Termination'
                    }
                },
                callback(r) {
                    if (r.message) {
                        frappe.show_alert({
                            message: __(`Employee Separation <b>${r.message.name}</b> created.`),
                            indicator: 'green'
                        }, 8);
                        window.open(`/app/employee-separation/${r.message.name}`, '_blank');
                        if (frm.fields_dict['employee_separation']) {
                            frm.set_value('employee_separation', r.message.name);
                            frm.save();
                        }
                    }
                }
            });
        }
    );
}

function trigger_forced_leave(frm) {
    frappe.prompt([
        {
            label:     'From Date',
            fieldname: 'from_date',
            fieldtype: 'Date',
            reqd:      1,
            default:   frappe.datetime.get_today()
        },
        {
            label:     'To Date (if known)',
            fieldname: 'to_date',
            fieldtype: 'Date'
        },
        {
            label:     'Reason / Notes',
            fieldname: 'reason',
            fieldtype: 'Small Text',
            reqd:      1,
            default:   `Pending Summary Dismissal — Disciplinary Case ${frm.doc.name}`
        }
    ],
    (values) => {
        frappe.call({
            method: 'frappe.client.insert',
            args: {
                doc: {
                    doctype:           'Forced leave',
                    employee:          frm.doc.employee,
                    employee_name:     frm.doc.employee_name,
                    department:        frm.doc.department,
                    start_date:         values.from_date,
                    end_date:           values.to_date || null,
                    reason:            values.reason,
                    disciplinary_case_no: frm.doc.name,
                    leave_type: 'Forced Leave'
                }
            },
            callback(r) {
                if (r.message) {
                    frappe.show_alert({
                        message: __(`Forced Leave <b>${r.message.name}</b> created.`),
                        indicator: 'green'
                    }, 8);
                    window.open(`/app/forced-leave/${r.message.name}`, '_blank');
                }
            }
        });
    },
    __('Create Forced Leave Record'),
    __('Create')
    );
}


// ============================================================
// CUSTOM BUTTONS
// ============================================================

function setup_custom_buttons(frm) {
    if (frm.is_new()) return;

    const state = frm.doc.workflow_state;

    if (state === 'Hearing Outcome') {
        frm.add_custom_button(__('Populate Verdict Table'), () => {
            populate_verdict_from_charges(frm);
            frappe.show_alert({ message: __('Verdict table populated from charges.'), indicator: 'green' }, 4);
        }, __('Actions'));
    }

    if (state === 'Appeal Outcome') {
        frm.add_custom_button(__('Populate Appeal Verdict'), () => {
            populate_appeal_verdict_from_verdict(frm);
            frappe.show_alert({ message: __('Appeal verdict table populated from hearing outcomes.'), indicator: 'green' }, 4);
        }, __('Actions'));
    }

    if (state === 'Pending DG Approval') {
        frm.add_custom_button(__('Record Rejection Reason'), () => {
            show_ceo_rejection_prompt(frm);
        }, __('Actions'));
    }

    const sd_states = ['Awaiting Employee Decision', 'Case Closed'];
    if (sd_states.includes(state) && outcome_is_summary_dismissal(frm)) {
        frm.add_custom_button(__('Create Employee Separation'), () => {
            create_employee_separation(frm);
        }, __('Summary Dismissal Actions'));

        frm.add_custom_button(__('Trigger Forced Leave'), () => {
            trigger_forced_leave(frm);
        }, __('Summary Dismissal Actions'));
    }

    if (frm.doc.employee) {
        frm.add_custom_button(__('View Breach History'), () => {
            show_breach_history(frm);
        }, __('Actions'));
    }

    if (state !== 'Draft') {
        frm.add_custom_button(__('Print Case Summary'), () => {
            const url = `/printview?doctype=Disciplinary&name=${frm.doc.name}&format=Disciplinary Report&no_letterhead=0`;
            window.open(url, '_blank');
        }, __('Actions'));
    }
}


// ============================================================
// BREACH HISTORY DIALOG
// ============================================================

function show_breach_history(frm) {
    frappe.call({
        method: 'frappe.client.get_list',
        args: {
            doctype:           'Disciplinary',
            filters:           [['employee', '=', frm.doc.employee], ['name', '!=', frm.doc.name || '']],
            fields:            ['name', 'workflow_state', 'creation'],
            order_by:          'creation desc',
            limit_page_length: 100
        },
        callback(r) {
            if (!r.message || r.message.length === 0) {
                frappe.msgprint(__('No prior disciplinary cases found for this employee.'));
                return;
            }

            let table_html = `
                <table class="table table-bordered table-sm">
                    <thead>
                        <tr>
                            <th>Case</th>
                            <th>Date of Occurrence</th>
                            <th>Status</th>
                            <th>Charges</th>
                        </tr>
                    </thead>
                    <tbody>`;

            let pending   = r.message.length;
            let rows_html = [];

            r.message.forEach((doc, idx) => {
                frappe.db.get_doc('Disciplinary', doc.name).then((full_doc) => {
                    const charges = (full_doc.charge_description || []).map(c =>
                        `<li>
                            ${c.specific_offence} — ${c.breach_number} — <b>${c.prescribed_sanction}</b>
                            ${c.warning_expiry_date ? ' <span style="color:#666;">(Expires: ' + c.warning_expiry_date + ')</span>' : ''}
                        </li>`
                    ).join('');

                    const status_color = doc.workflow_state === 'Case Closed' ? '#27ae60' : '#e67e22';

                    rows_html[idx] = `<tr>
                        <td>
                            <a href="/app/disciplinary/${doc.name}" target="_blank">${doc.name}</a>
                        </td>
                        <td>${doc.creation || '-'}</td>
                        <td>
                            <span style="color:${status_color};font-weight:600;">
                                ${doc.workflow_state}
                            </span>
                        </td>
                        <td><ul style="margin:0;padding-left:16px;">${charges}</ul></td>
                    </tr>`;

                    pending--;
                    if (pending === 0) {
                        table_html += rows_html.join('') + '</tbody></table>';
                        frappe.msgprint({
                            title:   __(`Breach History — ${frm.doc.employee_name}`),
                            message: table_html,
                            wide:    true
                        });
                    }
                });
            });
        }
    });
}


